 const at=d=>{const x=ox+dx*d,y=oy+dy*d,z=oz+dz*d,length=Math.hypot(x,y,z),u=(Math.atan2(z,-x)/Math.PI/2+1)%1,v=Math.acos(Math.max(-1,Math.min(1,y/length)))/Math.PI;return {d,u,v,length,f:length-r-sampleHeight(t,u,v)};};
