// GLSL shared by all rocky bodies. Heights stay at their measured kilometre scale.
export const terrainGLSL=`uniform sampler2D heightMap;uniform bool hasHeight;uniform vec2 heightBounds;uniform vec2 heightStep;uniform float radiusKm;
float measuredHeight(vec2 uv){if(!hasHeight)return 0.;vec2 rg=texture2D(heightMap,uv).rg;return heightBounds.x+(rg.r*65280.+rg.g*255.)/65535.*heightBounds.y;}
vec3 measuredNormal(vec2 uv,vec3 radial){if(!hasHeight)return radial;float phi=uv.x*6.2831853,theta=(1.-uv.y)*3.14159265;vec3 tu=vec3(sin(phi),0.,cos(phi)),tv=vec3(cos(phi)*cos(theta),sin(theta),-sin(phi)*cos(theta));float gu=(measuredHeight(uv+vec2(heightStep.x,0.))-measuredHeight(uv-vec2(heightStep.x,0.)))/(12.5663706*radiusKm*max(.02,sin(theta))*heightStep.x);float gv=(measuredHeight(uv+vec2(0.,heightStep.y))-measuredHeight(uv-vec2(0.,heightStep.y)))/(6.2831853*radiusKm*heightStep.y);return normalize(radial-tu*gu-tv*gv);}`;
